import { useState, type FormEvent } from 'react';
import {
  Alert,
  Button,
  Card,
  Field,
  Input,
  Select,
  Stack,
  Switch,
} from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLES: Array<{ value: Role; label: string }> = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const trimmed = email.trim();
  const isValid = EMAIL_PATTERN.test(trimmed);
  const showError = touched && !isValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(trimmed);
    setEmail('');
    setTouched(false);
  };

  return (
    <Stack direction="column" gap="var(--jx-space-4)">
      {invitedEmail && (
        <Alert
          variant="success"
          title="Приглашение отправлено"
          closable
          onClose={() => setInvitedEmail(null)}
        >
          {invitedEmail} получит доступ к команде.
        </Alert>
      )}

      <Card>
        <form onSubmit={handleSubmit} noValidate>
          <Stack direction="column" gap="var(--jx-space-4)">
            <Field
              label="Почта"
              htmlFor="invite-email"
              required
              hint="Рабочий адрес участника, например name@company.com"
              error={showError ? 'Введите корректный адрес почты' : undefined}
            >
              <Input
                id="invite-email"
                type="email"
                value={email}
                placeholder="name@company.com"
                invalid={showError}
                autoComplete="email"
                onChange={(event) => setEmail(event.target.value)}
                onBlur={() => setTouched(true)}
              />
            </Field>

            <Field label="Роль" htmlFor="invite-role">
              <Select
                id="invite-role"
                value={role}
                onChange={(event) => setRole(event.target.value as Role)}
              >
                {ROLES.map((item) => (
                  <option key={item.value} value={item.value}>
                    {item.label}
                  </option>
                ))}
              </Select>
            </Field>

            <Switch
              checked={notify}
              label="Отправить уведомление"
              onChange={(event) => setNotify(event.target.checked)}
            />

            <Button type="submit" variant="primary" disabled={!isValid}>
              Отправить приглашение
            </Button>
          </Stack>
        </form>
      </Card>
    </Stack>
  );
}

